1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	import java.time.LocalDate;
6	
7	/**
8	 * Derives an owner's membership standing from the state captured when the owner
9	 * was created together with how long the owner has been registered. Kept as a
10	 * plain static helper - rather than a method on {@link OwnerMapper} - so
11	 * MapStruct does not mistake it for an implicit property mapping.
12	 *
13	 * <p>Standing is scored as points, starting at 0: an email address is worth 2,
14	 * a name that was unique on create ({@code namesakeCount} is 0) is worth 1, a
15	 * household of 3 or more members is worth 2, and tenure exceeding
16	 * {@link #TENURE_DAYS_FOR_BONUS} days is worth 3. Those points map to a numeric
17	 * membership level: 1 (0-1 points), 2 (2-3 points), 3 (4-5 points) and 4 (6 or
18	 * more points). Tenure is measured in elapsed fiscal years (fiscal years start
19	 * on 1 July).
20	 */
21	public final class MembershipLevel {
22	
23	    /** Points awarded when an email address is present. */
24	    private static final int EMAIL_POINTS = 2;
25	
26	    /** Points awarded when the name was unique on create (namesakeCount is 0). */
27	    private static final int UNIQUE_NAME_POINTS = 1;
28	
29	    /** Points awarded for a household of 3 or more members. */
30	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
31	
32	    /** Points awarded when tenure exceeds {@link #TENURE_FISCAL_YEARS_FOR_BONUS} fiscal years. */
33	    private static final int TENURE_POINTS = 3;
34	
35	    /** Household size, in members, at or above which the household bonus applies. */
36	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
37	
38	    /** Tenure, in elapsed fiscal years, that must be exceeded to earn the tenure bonus. */
39	    private static final int TENURE_FISCAL_YEARS_FOR_BONUS = 1;
40	
41	    private MembershipLevel() {
42	    }
43	
44	    /**
45	     * Computes the owner's membership points: 0, plus {@value #EMAIL_POINTS} when
46	     * an email address is present, plus {@value #UNIQUE_NAME_POINTS} when
47	     * {@code namesakeCount} is 0, plus {@value #LARGE_HOUSEHOLD_POINTS} for a
48	     * household of {@value #LARGE_HOUSEHOLD_SIZE} or more members, plus
49	     * {@value #TENURE_POINTS} when the owner's tenure exceeds
50	     * {@link #TENURE_FISCAL_YEARS_FOR_BONUS} elapsed fiscal years.
51	     *
52	     * @param owner the owner whose points to derive
53	     * @return the owner's membership points
54	     */
55	    public static int pointsForOwner(Owner owner) {
56	        int points = 0;
57	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
58	            points += EMAIL_POINTS;
59	        }
60	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
61	            points += UNIQUE_NAME_POINTS;
62	        }
63	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= LARGE_HOUSEHOLD_SIZE) {
64	            points += LARGE_HOUSEHOLD_POINTS;
65	        }
66	        if (tenureExceedsBonusThreshold(owner.getRegistrationDate())) {
67	            points += TENURE_POINTS;
68	        }
69	        return points;
70	    }
71	
72	    /**
73	     * Maps the owner's membership points to a numeric membership level: 1 for
74	     * 0-1 points, 2 for 2-3 points, 3 for 4-5 points and 4 for 6 or more points.
75	     *
76	     * @param owner the owner whose level to derive
77	     * @return the numeric membership level between 1 and 4 inclusive
78	     */
79	    public static int forOwner(Owner owner) {
80	        return levelForPoints(pointsForOwner(owner));
81	    }
82	
83	    /**
84	     * Maps a membership-points total to its membership level: 1 (0-1), 2 (2-3),
85	     * 3 (4-5), 4 (6 or more).
86	     *
87	     * @param points the membership points
88	     * @return the corresponding membership level between 1 and 4 inclusive
89	     */
90	    public static int levelForPoints(int points) {
91	        if (points >= 6) {
92	            return 4;
93	        }
94	        if (points >= 4) {
95	            return 3;
96	        }
97	        if (points >= 2) {
98	            return 2;
99	        }
100	        return 1;
101	    }
102	
103	    /**
104	     * Returns whether the tenure elapsed since {@code registrationDate}, counted
105	     * in whole fiscal years (fiscal years start on 1 July), is more than
106	     * {@link #TENURE_FISCAL_YEARS_FOR_BONUS} fiscal years. A {@code null} or future
107	     * registration date yields zero (or negative) tenure and therefore never
108	     * qualifies.
109	     *
110	     * @param registrationDate the day the owner was registered, or {@code null}
111	     * @return {@code true} when tenure exceeds the tenure-bonus threshold
112	     */
113	    private static boolean tenureExceedsBonusThreshold(LocalDate registrationDate) {
114	        if (registrationDate == null) {
115	            return false;
116	        }
117	        int elapsedFiscalYears = FiscalYear.startYear(LocalDate.now())
118	            - FiscalYear.startYear(registrationDate);
119	        return elapsedFiscalYears > TENURE_FISCAL_YEARS_FOR_BONUS;
120	    }
121	
122	}
